define('DOING_AJAX',true);require '/scratch/site/wp-load.php';if('local'!==wp_get_environment_type()||CAS_Bunny_Uploader::config()['library_key']!=='synthetic-library-key-not-real')throw new Exception('Synthetic fixture required');$f=json_decode(file_get_contents('/scratch/fixture.json'),true);wp_set_current_user($f['users']['floweditor']);$checks=0;$created=0;class DraftPriceJsonExit extends Exception{}add_filter('wp_die_ajax_handler',fn()=>function(){throw new DraftPriceJsonExit;});function verify($v,$m){global$checks;if(!$v)throw new Exception($m);++$checks;}function ajax($action,$data=[]){$_SERVER['REQUEST_METHOD']='POST';$_POST=wp_slash(array_merge(['action'=>$action,tutor()->nonce=>wp_create_nonce(tutor()->nonce_action)],$data));$_REQUEST=$_POST;ob_start();try{do_action('wp_ajax_'.$action);throw new Exception('Expected response');}catch(DraftPriceJsonExit $e){$out=ob_get_clean();$d=json_decode($out,true);if(!$d)throw new Exception('Invalid JSON '.substr($out,0,200));$d['_http_status']=http_response_code();return$d;}catch(Throwable$e){ob_end_clean();CAS_Bunny_Uploader::rollback();throw$e;}}
try{$r=ajax('tutor_create_new_draft_course');verify($r['status_code']===201,'Native restricted draft creation');parse_str(parse_url($r['data'],PHP_URL_QUERY),$q);$created=(int)$q['course_id'];verify(get_post_meta($created,CAS_PRICE_PENDING_META,true)!=='','First price pending');verify(get_post_meta($created,'_tutor_course_price_type',true)==='paid','Stored paid state');$details=ajax('tutor_course_details',['course_id'=>$created]);verify($details['data']['course_pricing']['type']==='free','Form-only non-monetary draft placeholder');$input=['course_id'=>$created,'post_author'=>get_current_user_id(),'post_title'=>'Unpriced draft can save content','post_content'=>'Still private; no price confirmed','post_status'=>'draft','course_level'=>'beginner','enable_qna'=>'no','is_public_course'=>'no','_tutor_course_additional_data_edit'=>'true','pricing'=>['type'=>'free'],'course_price'=>'','course_sale_price'=>''];$r=ajax('tutor_update_course',$input);verify($r['status_code']===200,'Draft content save before first price '.json_encode($r));verify(get_post_status($created)==='draft'&&get_the_title($created)===$input['post_title'],'Draft content persisted');verify(get_post_meta($created,'_tutor_course_price_type',true)==='paid'&&cas_price_current($created)['regular']==='','No free course or price established');verify((bool)get_post_meta($created,CAS_PRICE_PENDING_META,true),'Price confirmation still required');$forged=$input;$forged['course_price']='9.00';$rejected=ajax('tutor_update_course',$forged);verify(($rejected['status_code']??$rejected['_http_status'])===409,'Unconfirmed price bypass refused');$publish=$input;$publish['post_status']='publish';$rejected=ajax('tutor_update_course',$publish);verify(($rejected['status_code']??$rejected['_http_status'])===409,'Unpriced publication refused');verify(get_post_status($created)==='draft','Still private after refusal');echo json_encode(['passed'=>true,'assertions'=>$checks])."\n";}finally{CAS_Bunny_Uploader::rollback();$_POST=[];$_REQUEST=[];if($created){wp_set_current_user(1);global $wpdb;if('courses'!==get_post_type($created)||(int)get_post_field('post_author',$created)!==(int)$f['users']['floweditor']||get_post_status($created)!=='draft')throw new Exception('Unexpected synthetic cleanup target');$wpdb->delete($wpdb->postmeta,['post_id'=>$created]);$wpdb->delete($wpdb->term_relationships,['object_id'=>$created]);$wpdb->delete($wpdb->posts,['ID'=>$created]);clean_post_cache($created);delete_user_meta($f['users']['floweditor'],'_tutor_instructor_course_id',$created);}}
